/* ============================================================
   KONFIGURASI PENUTUPAN APLIKASI (MANUAL SAJA)
   ============================================================
   Catatan penting:
   - localStorage hanya berlaku di browser/perangkat yang sama.
   - Agar tombol tutup/buka berlaku untuk SEMUA browser siswa, Google Apps Script
     perlu menyimpan status aplikasi secara global dan mendukung action:
     getAppStatus serta setAppStatus. Frontend ini sudah mencoba memakai action
     tersebut, lalu fallback ke localStorage jika belum tersedia.
   ============================================================ */
const APP_CLOSE_KEY = 'smpn9_app_manual_closed';

async function getServerAppStatus() {
  try {
    const url = `${CONFIG.APPS_SCRIPT_URL}?action=getAppStatus&t=${Date.now()}`;
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const json = await res.json();
    if (json.status === 'error') throw new Error(json.message || 'Server tidak mendukung getAppStatus');

    const data = json.data || json;
    if (typeof data.closed === 'boolean') return { closed: data.closed, source: 'server' };
    if (typeof data.appClosed === 'boolean') return { closed: data.appClosed, source: 'server' };
    if (typeof data.manualClosed === 'boolean') return { closed: data.manualClosed, source: 'server' };
    return null;
  } catch (err) {
    console.warn('Status global dari Apps Script belum tersedia:', err.message);
    return null;
  }
}

async function setServerAppStatus(closed) {
  const payload = { action: 'setAppStatus', closed };
  const res = await fetch(CONFIG.APPS_SCRIPT_URL, {
    method: 'POST',
    // Tanpa custom header agar request lebih kompatibel dengan Google Apps Script/CORS.
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const json = await res.json();
  if (json.status === 'error') throw new Error(json.message || 'Server tidak mendukung setAppStatus');
  return json;
}

/** Cek apakah login siswa ditutup. Jadwal otomatis sudah dihapus. */
async function isAppClosed() {
  const serverStatus = await getServerAppStatus();
  if (serverStatus) return { closed: serverStatus.closed, reason: 'manual', source: 'server' };

  // Fallback lama: hanya browser/perangkat ini.
  if (localStorage.getItem(APP_CLOSE_KEY) === 'true') {
    return { closed: true, reason: 'manual', source: 'local' };
  }
  return { closed: false, source: 'local' };
}

/** Update tampilan status di section pengaturan secara lokal tanpa fetch ulang */
function updateSettingsStatusLocal(closed, source) {
  const card  = document.getElementById('settings-status-card');
  const ico   = document.getElementById('settings-status-ico');
  const val   = document.getElementById('settings-status-val');
  const sub   = document.getElementById('settings-status-sub');
  const btnT  = document.getElementById('btn-tutup-app');
  const btnB  = document.getElementById('btn-buka-app');
  if (!card) return;

  if (closed) {
    card.className = 'settings-status-card status-closed';
    if (ico) ico.className  = 'bi bi-lock-fill';
    if (val) val.textContent = 'TERTUTUP';
    if (sub) sub.textContent = source === 'server'
      ? 'Ditutup secara manual oleh administrator dan berlaku untuk semua browser.'
      : 'Ditutup secara manual, tetapi status ini hanya tersimpan di browser/perangkat ini.';
    if (btnT) btnT.disabled = true;
    if (btnB) btnB.disabled = false;
  } else {
    card.className = 'settings-status-card status-open';
    if (ico) ico.className  = 'bi bi-unlock-fill';
    if (val) val.textContent = 'TERBUKA';
    if (sub) sub.textContent = source === 'server'
      ? 'Siswa dapat login. Status dibaca dari server/global.'
      : 'Siswa dapat login. Status global server belum aktif; localStorage hanya berlaku di browser ini.';
    if (btnT) btnT.disabled = false;
    if (btnB) btnB.disabled = true;
  }
}

/** Tutup aplikasi manual (admin) */
async function adminTutupAplikasi() {
  try {
    const btnT  = document.getElementById('btn-tutup-app');
    const btnB  = document.getElementById('btn-buka-app');
    if (btnT) btnT.disabled = true;
    if (btnB) btnB.disabled = true;

    await setServerAppStatus(true);
    localStorage.setItem(APP_CLOSE_KEY, 'true');
    showAlert('settings-action-alert', '<i class="bi bi-lock-fill"></i> Akses login siswa berhasil <strong>ditutup untuk semua browser</strong>.', 'danger');
    updateSettingsStatusLocal(true, 'server');
  } catch (err) {
    localStorage.setItem(APP_CLOSE_KEY, 'true');
    showAlert('settings-action-alert', '<i class="bi bi-exclamation-triangle-fill"></i> Server belum mendukung status global, jadi penutupan hanya tersimpan di <strong>browser admin ini</strong>. Tambahkan action <code>getAppStatus</code>/<code>setAppStatus</code> di Google Apps Script agar berlaku untuk semua browser.', 'danger');
    updateSettingsStatusLocal(true, 'local');
  }
}

/** Buka / reset aplikasi (admin) */
async function adminBukaAplikasi() {
  try {
    const btnT  = document.getElementById('btn-tutup-app');
    const btnB  = document.getElementById('btn-buka-app');
    if (btnT) btnT.disabled = true;
    if (btnB) btnB.disabled = true;

    await setServerAppStatus(false);
    localStorage.removeItem(APP_CLOSE_KEY);
    showAlert('settings-action-alert', '<i class="bi bi-unlock-fill"></i> Akses login siswa berhasil <strong>dibuka kembali untuk semua browser</strong>.', 'success');
    updateSettingsStatusLocal(false, 'server');
  } catch (err) {
    localStorage.removeItem(APP_CLOSE_KEY);
    showAlert('settings-action-alert', '<i class="bi bi-info-circle-fill"></i> Server belum mendukung status global, jadi pembukaan hanya tersimpan di <strong>browser admin ini</strong>.', 'info');
    updateSettingsStatusLocal(false, 'local');
  }
}

/** Update tampilan status di section pengaturan */
async function updateSettingsStatus() {
  const card  = document.getElementById('settings-status-card');
  const ico   = document.getElementById('settings-status-ico');
  const val   = document.getElementById('settings-status-val');
  const sub   = document.getElementById('settings-status-sub');
  const btnT  = document.getElementById('btn-tutup-app');
  const btnB  = document.getElementById('btn-buka-app');
  if (!card) return;

  const { closed, source } = await isAppClosed();

  if (closed) {
    card.className = 'settings-status-card status-closed';
    ico.className  = 'bi bi-lock-fill';
    val.textContent = 'TERTUTUP';
    sub.textContent = source === 'server'
      ? 'Ditutup secara manual oleh administrator dan berlaku untuk semua browser.'
      : 'Ditutup secara manual, tetapi status ini hanya tersimpan di browser/perangkat ini.';
    if (btnT) btnT.disabled = true;
    if (btnB) btnB.disabled = false;
  } else {
    card.className = 'settings-status-card status-open';
    ico.className  = 'bi bi-unlock-fill';
    val.textContent = 'TERBUKA';
    sub.textContent = source === 'server'
      ? 'Siswa dapat login. Status dibaca dari server/global.'
      : 'Siswa dapat login. Status global server belum aktif; localStorage hanya berlaku di browser ini.';
    if (btnT) btnT.disabled = false;
    if (btnB) btnB.disabled = true;
  }
}


